from datetime import timedelta
from temporalio import activity, workflow

@activity.defn
async def search(question: str) -> str:
    ...  # call a search API

@activity.defn
async def ask_llm(question: str, context: str) -> str:
    ...  # call your LLM

@workflow.defn
class ResearchWorkflow:
    @workflow.run
    async def run(self, question: str) -> str:
        context = await workflow.execute_activity(
            search, question, start_to_close_timeout=timedelta(seconds=30)
        )
        return await workflow.execute_activity(
            ask_llm, args=[question, context], start_to_close_timeout=timedelta(minutes=2)
        )
